    int b0 = bb.get() & 0xFF;
    if ((b0 & 0x80) == 0) {
        sb.append((char) b0);
    } else if ((b0 & 0xE0) == 0xC0) {
        int b1 = bb.get() & 0xFF;
        int cp = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        sb.append((char) cp);
    } else if ((b0 & 0xF0) == 0xE0) {
        int b1 = bb.get() & 0xFF;
        int b2 = bb.get() & 0xFF;
        int cp = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        sb.append((char) cp);
    } else if ((b0 & 0xF8) == 0xF0) {
        int b1 = bb.get() & 0xFF;
        int b2 = bb.get() & 0xFF;
        int b3 = bb.get() & 0xFF;
        int cp = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        int high = ((cp - 0x10000) >> 10) + 0xD800;
        int low = ((cp - 0x10000) & 0x3FF) + 0xDC00;
        sb.append((char) high);
        sb.append((char) low);
    } else {
