    // Search for the next CRLF sequence after the current end index
    for (int i = end + 1; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            // Return the index of the LF character, which marks the end of the line
            return i + 1;
        }
    }
    // If no CRLF is found, indicate failure
    return -1;
}

