public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int start = 0;
    if (path.startsWith("/")) {
        start = 1; // ignore leading slash for absolute paths
    }
    while (start <= path.length()) {
        int end = path.indexOf('/', start);
        if (end == -1) {
            end = path.length();
        }
        String seg = path.substring(start, end);
        String value = seg;
        if (decode) {
            try {
                value = new URI(null, null, seg, null).getPath();
            } catch (URISyntaxException e) {
                // If decoding fails, keep the original segment
            }
        }
        segments.add(new PathSegmentImpl(value));
        start = end + 1;
    }
    return segments;
}

