    }
    while (true) {
        boolean isPrime = true;
        if (candidate < 2) {
            isPrime = false;
        } else if (candidate == 2) {
            isPrime = true;
        } else if (candidate % 2 == 0) {
            isPrime = false;
        } else {
            int sqrt = (int) Math.sqrt(candidate);
            for (int i = 3; i <= sqrt; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2;
        // If desiredCapacity >= 1000, we prefer a prime within 11% of desiredCapacity.
        // However, if none found within that range, we continue searching beyond the limit.
    }
}

