protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty() || graph == null) return null;
    // Create a mutable copy of the set to track remaining edges
    Set<E> remaining = new java.util.HashSet<>(tour);
    // Pick an arbitrary starting edge
    E firstEdge = remaining.iterator().next();
    remaining.remove(firstEdge);
    java.util.List<E> orderedEdges = new java.util.ArrayList<>();
    orderedEdges.add(firstEdge);
    // Determine the starting vertex
    V currentVertex = graph.getEdgeSource(firstEdge);
    V startVertex = currentVertex;
    // Build the tour by following edges
    while (!remaining.isEmpty()){
        boolean found = false;
        for (E e : remaining){
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex) || tgt.equals(currentVertex)){
                // Use this edge
                remaining.remove(e);
                orderedEdges.add(e);
                // Move to the other vertex
                currentVertex = src.equals(currentVertex) ? tgt : src;
                found = true;
                break;
            }
        }
        if (!found){
            // The set does not form a continuous tour
            return null;
        }
    }
    // Compute total weight
    double weight = 0.0;
    for (E e : orderedEdges){
        weight += graph.getEdgeWeight(e);
    }
    // The end vertex should be the same as the start for a tour
    V endVertex = currentVertex;
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, startVertex, endVertex, weight, orderedEdges);
}

